#include <string>

class ReloadWatcher
{
public:
    ReloadWatcher(long long loadedTime, int stablePolls) : m_loaded{ loadedTime }, m_needed{ stablePolls < 1 ? 1 : stablePolls } {}

    bool poll(long long fileTime)
    {
        if (fileTime == m_loaded) { m_seen = 0; return false; }
        if (m_seen > 0 && fileTime == m_candidate) ++m_seen;
        else { m_candidate = fileTime; m_seen = 1; }
        if (m_seen < m_needed) return false;
        m_loaded = fileTime;
        m_seen = 0;
        ++m_generation;
        return true;
    }

    int generation() const { return m_generation; }
    std::string copyName() const { return "gameplay_" + std::to_string(m_generation) + ".dll"; }

private:
    long long m_loaded;
    int m_needed;
    long long m_candidate{ 0 };
    int m_seen{ 0 };
    int m_generation{ 0 };
};

unitTests:
TEST("the example") { ReloadWatcher w{ 100, 3 }; CHECK(!w.poll(100)); CHECK(!w.poll(150)); CHECK(!w.poll(150)); CHECK(w.poll(150)); CHECK_EQ(w.generation(), 1); CHECK_EQ(w.copyName(), std::string("gameplay_1.dll")); CHECK(!w.poll(150)); }
TEST("before any reload") { ReloadWatcher w{ 1, 2 }; CHECK_EQ(w.copyName(), std::string("gameplay_0.dll")); CHECK_EQ(w.generation(), 0); }
TEST("time still changing") { ReloadWatcher w{ 100, 2 }; CHECK(!w.poll(110)); CHECK(!w.poll(120)); CHECK(!w.poll(130)); CHECK(w.poll(130)); CHECK_EQ(w.generation(), 1); }
TEST("build undone") { ReloadWatcher w{ 100, 3 }; CHECK(!w.poll(200)); CHECK(!w.poll(200)); CHECK(!w.poll(100)); CHECK(!w.poll(200)); CHECK(!w.poll(200)); CHECK(w.poll(200)); }
TEST("one poll is enough") { ReloadWatcher w{ 5, 1 }; CHECK(w.poll(6)); CHECK(w.poll(7)); CHECK_EQ(w.generation(), 2); CHECK_EQ(w.copyName(), std::string("gameplay_2.dll")); }
TEST("several reloads") { ReloadWatcher w{ 0, 2 }; w.poll(1); CHECK(w.poll(1)); w.poll(2); CHECK(w.poll(2)); CHECK(!w.poll(2)); CHECK_EQ(w.generation(), 2); }

